-- BÀI 26 (2 bài đọc)
-- =========================================================
-- Reading Content: 宇宙ステーションの生活はどうですか
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '宇宙ステーションの生活はどうですか', '――宇宙ステーションはどこにあるんですか。
地球から400キロ上を飛んでいます。
――えっ？ ステーションが飛んでいるんですか。
はい。90分で1回地球を回っています。1日に16回朝と夜が来るんですよ。
――じゃ、寝る時間や起きる時間はどうやってわかるんですか。
グリニッジ標準時を使っています。
――どうして宇宙ステーションの中ではいつも「泳いで」いるんですか。
宇宙は重力がありませんから、歩くことができないんです。
――いつも宇宙服を着ているんですか。
いいえ。宇宙服はステーションの外に出て仕事をするとき、着ます。ステーションの中は普通の服を着ています。
――服は洗濯するんですか。
いいえ。宇宙では水が大切ですから、洗濯しません。4、5日着て、捨てます。
――水も地球から運んでいるんですか。
はい。でも、水は重いですから、たくさん運ぶことができません。ですから、わたしたちのおしっこから水を作っています。飲むこともできるんですよ。
――リサイクルですね。じゃ、おふろは？
ありません。もちろんシャワーもありません。代わりに体をふきます。
――雑誌で読んだんですが、宇宙で生活すると、背が高くなるんですか。
ええ、宇宙では、1～7センチ高くなります。しかし、地球へ帰ったら、まえと同じになります。
――10年宇宙にいたら、どうなるんですか。
まだ、わかりません。今、研究しています。
（参考：JAXA 宇宙航空研究開発機構HP）', 'Cuộc sống ở trạm vũ trụ như thế nào?
- Trạm vũ trụ ở đâu vậy?
Nó đang bay ở độ cao 400 km trên Trái Đất.
- Hả? Trạm vũ trụ đang bay sao?
Vâng. Cứ 90 phút lại quay quanh Trái Đất 1 vòng. Một ngày có tới 16 lần buổi sáng và buổi tối đấy.
- Vậy làm sao biết được giờ ngủ hay giờ thức?
Chúng tôi sử dụng giờ chuẩn Greenwich.
- Tại sao trong trạm vũ trụ mọi người lúc nào cũng ''bơi'' vậy?
Vì ngoài vũ trụ không có trọng lực, nên không thể đi bộ được.
- Mọi người lúc nào cũng mặc bộ đồ du hành vũ trụ à?
Không. Bộ đồ vũ trụ chỉ mặc khi ra ngoài trạm làm việc. Ở trong trạm thì mặc quần áo bình thường.
- Quần áo có giặt không?
Không. Ngoài vũ trụ nước rất quý nên không giặt. Mặc 4-5 ngày rồi vứt đi.
- Nước cũng được chở từ Trái Đất lên à?
Vâng. Nhưng nước nặng nên không thể chở nhiều được. Vì vậy chúng tôi tái chế nước từ nước tiểu. Nước đó uống được đấy.
- Tái chế nhỉ! Vậy còn tắm rửa thì sao?
Không có bồn tắm. Đương nhiên vòi hoa sen cũng không có. Thay vào đó, chúng tôi lau người.
- Tôi đọc tạp chí thấy bảo sống ngoài vũ trụ thì chiều cao tăng lên đúng không?
Vâng, ngoài vũ trụ sẽ cao thêm 1-7 cm. Nhưng khi về Trái Đất thì sẽ trở lại như cũ.
- Nếu ở ngoài vũ trụ 10 năm thì sẽ thế nào?
Vẫn chưa biết được. Hiện tại các nhà khoa học đang nghiên cứu.', '/media/reading/reading_n4_l26_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '宇宙ステーションの生活はどうですか');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 宇宙では暗くなったら寝て、明るくなったら起きる。', 'MULTIPLE_CHOICE', '90分で1回地球を回り、1日に16回朝と夜が来るため、グリニッジ標準時を使って時間を決めています。(✕)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND rc.title = '宇宙ステーションの生活はどうですか' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '〇', FALSE, 1 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND rc.title = '宇宙ステーションの生活はどうですか' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '✕', TRUE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND rc.title = '宇宙ステーションの生活はどうですか' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '2) ステーションではおふろに入ったり、洗濯したりすることができない。', 'MULTIPLE_CHOICE', 'おふろもシャワーもなく代わりに体をふき、水が大切なので洗濯もしません。(〇)', NULL, 2 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND rc.title = '宇宙ステーションの生活はどうですか' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 2);
