INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '✕', FALSE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND rc.title = '宇宙ステーションの生活はどうですか' AND rq.sort_order = 2 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '3) ステーションで使う水は全部地球から運んでいる。', 'MULTIPLE_CHOICE', '水は重くてたくさん運べないため、おしっこから水を作ってリサイクルしています。(✕)', NULL, 3 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND rc.title = '宇宙ステーションの生活はどうですか' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 3);
