-- Reading Content: クイズ 宇宙
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'クイズ 宇宙', '宇宙についてのクイズです。宇宙での生活や宇宙の知識について考えてみましょう。

1. 地球から宇宙ステーションまでどのくらいかかりますか。
2. 地球を90分で回る宇宙ステーションは時速何キロで飛んでいますか。
3. 宇宙ステーションの大きさ（広さ）はどのくらいですか。
4. コップ1杯の水を宇宙に運びます。いくらかかりますか。
5. 宇宙服は何キロありますか。
6. 宇宙ステーションに何人住むことができますか。
7. 宇宙には空気がありません。空気がなかったら、どうなりますか。
8. 次の人で、宇宙飛行士はどの人ですか。
9. 世界で初めて月へ行った人はどこの国の人ですか。', 'Câu đố về vũ trụ: Hãy cùng kiểm tra các kiến thức thú vị về cuộc sống và môi trường trong không gian.', '/media/reading/reading_n4_l26_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'クイズ 宇宙');
