INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '② 6日', FALSE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 26 AND rc.title = 'クイズ 宇宙' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
