-- BÀI 27 (1 bài đọc)
-- =========================================================
-- Reading Content: 忍者
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '忍者', '忍者は昔のスパイだ。忍者は厳しい訓練をしたから、いろいろなことができた。スポーツの選手と同じだ。とても速く歩いたり、走ったりすることができた。高い壁を登ることや長い時間水の中にいることもできた。目や耳がよかったから、遠い所がよく見えた。小さい音でもよく聞こえた。
映画やマンガでは時々おもしろいまちがいがある。映画やマンガの忍者は水の上を歩いたり、空を飛んだりしている。でも、実際は無理だ。忍者はとても速く動いたり、いろいろな道具を使ったりした。それで、普通の人ができないことができたのだ。
滋賀県や三重県には昔、忍者が住んでいたうちがある。うちの中にはいろいろおもしろい物がある。部屋の壁の前に立つと、壁が回転して、人が消える。小さい秘密の部屋から隣や下の部屋の中が見られる。忍者が使ったいろいろな道具もある。でも、今、忍者には会えない。残念だ。', 'Ninja là điệp viên ngày xưa. Ninja trải qua quá trình huấn luyện vô cùng nghiêm ngặt nên có thể làm được nhiều việc khác nhau, tương tự như các vận động viên thể thao. Họ có thể đi bộ hoặc chạy rất nhanh, có thể leo tường cao và ở dưới nước trong thời gian dài. Mắt và tai rất thính nên nhìn được nơi xa và nghe thấy cả những âm thanh rất nhỏ.
Trong phim ảnh và truyện tranh thỉnh thoảng có những sự nhầm lẫn thú vị. Ninja trong phim đi trên mặt nước hay bay trên trời. Nhưng thực tế thì không thể làm vậy. Ninja di chuyển cực kỳ nhanh và sử dụng nhiều loại công cụ đặc biệt. Nhờ đó họ làm được những việc mà người bình thường không thể làm được.
Ở tỉnh Shiga và Mie ngày xưa có những ngôi nhà nơi ninja từng sinh sống. Trong nhà có rất nhiều điều kỳ thú. Đứng trước tường phòng, bức tường xoay tròn và người biến mất. Từ căn phòng bí mật nhỏ có thể nhìn thấy phòng bên cạnh hoặc phòng bên dưới. Ngoài ra còn có nhiều dụng cụ ninja từng sử dụng. Tuy nhiên, ngày nay ta không thể gặp lại ninja được nữa. Thật đáng tiếc.', '/media/reading/reading_n4_l27_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '忍者');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 忍者は昔のスパイだ。', 'MULTIPLE_CHOICE', '「忍者は昔のスパイだ」と本文にあります。(〇)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 27 AND rc.title = '忍者' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
