-- BÀI 29 (1 bài đọc)
-- =========================================================
-- Reading Content: わたしの失敗
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'わたしの失敗', '《ライトさん》
わたしは先週友達のうちへ遊びに行きました。大阪駅で来た電車にすぐ乗りました。友達はうちの近くの駅で待っていると言いました。でも、わたしが乗った電車はその駅を通り過ぎてしまいました。それは特急電車でした。京都までどこにも止まりませんでした。わたしはもう一度大阪へ行く電車に乗りました。友達は駅で2時間待っていてくれました。うれしかったです。

《ジョンさん》
先週日本人のうちにホームステイしました。晩ごはんのあとで、お母さんが「おふろ、どうぞ」と言ってくれました。日本のおふろは初めてでした。バスタブは大きくて、お湯がたくさん入っていました。お湯は少し熱かったです。お湯の中でゆっくり体を洗いました。そして汚れたお湯を全部捨てました。次にお父さんがおふろへ行きました。「あれ？ お湯が入っていない。」お父さんはびっくりしました。日本のおふろは、バスタブの外で体を洗ってから、中に入るんですね。知りませんでした。

《ミゲルさん》
わたしは水曜日の夜、日本人の友達のうちで、スペイン語を教えています。先週友達が「来月スペインへ旅行に行きますから、もっと勉強したいです」と言いました。わたしは「じゃ、土曜日も来ましょうか」と聞きました。彼は「土曜日はいいです」と言いました。土曜日に友達のうちへ行きました。家の電気は消えていました。ベルを押しましたが、返事がありませんでした。日曜日、彼に電話しました。「きのう、あなたのうちへ行きましたよ。」「『土曜日はいいです』と言ったでしょう？」', 'Những thất bại / sự cố đáng nhớ:
- Anh Wright: Lên nhầm tàu tốc hành Tokkyu đi thẳng tới Kyoto không dừng lại ở ga của bạn mình, khiến bạn phải đợi 2 tiếng.
- Anh John: Đi homestay tại nhà người Nhật, tắm trong bồn tắm rồi xả hết nước bẩn đi, khiến bố của gia đình chủ ngạc nhiên vì ở Nhật phải tắm rửa sạch sẽ bên ngoài bồn rồi mới vào ngâm nước.
- Anh Miguel: Dạy tiếng Tây Ban Nha cho bạn người Nhật, nghe bạn bảo ''Thứ Bảy thì được rồi (không cần đâu)'' nhưng lại tưởng là đồng ý, nên đến nhà không có ai.', '/media/reading/reading_n4_l29_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 29 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'わたしの失敗');
