-- Reading Content: 伝言メモ
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '伝言メモ', '日常でよく使われる伝言メモを読んでみましょう。

1) お帰りなさい。冷蔵庫にケーキとジュースが入れてあります。食べたら、お皿とコップは洗っておいてね。5時ごろ帰ります。
2) 大阪支店の佐藤さんから電話がありました。出張の予定を知らせておきました。会議の資料はメールで送っておきました。では、お先に失礼します。
3) きのうは本当にゴメン。僕が悪かった。今晩は早く帰る。
4) 掃除しました。机の上はそのままにしてあります。今晩の食事はカレーです。サラダは冷蔵庫に入れてあります。それから3時ごろ荷物が届きました。台所に置いてあります。あさっての午後また伺います。
5) 今晩8時からサッカーの試合が予約してあるから、晩ごはんは要らないよ。それから今晩は彼女と食事するから、絶対にビデオに触らないで。', 'Các mẩu giấy ghi nhắn (Memo):
1) Mẹ nhắn con: có bánh và nước trong tủ lạnh, ăn xong nhớ rửa.
2) Nhân viên nhắn Trưởng phòng: có điện thoại từ anh Sato chi nhánh Osaka, đã gửi tài liệu qua mail.
3) Chồng nhắn vợ: xin lỗi vì chuyện hôm qua, tối nay sẽ về sớm.
4) Người giúp việc nhắn chủ nhà: đã dọn dẹp, nấu cà ri, hàng gửi đến để ở bếp.
5) Con trai nhắn mẹ: tối nay hẹn hò và xem bóng đá, đừng động vào máy ghi hình.', '/media/reading/reading_n4_l30_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 30 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '伝言メモ');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) メモ1「お帰りなさい。冷蔵庫にケーキとジュースが...」はだれからだれへ？', 'MULTIPLE_CHOICE', 'お母さんから子どもへのメモです。(①)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 30 AND rc.title = '伝言メモ' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
