-- Reading Content: あなたは何年生まれ？
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'あなたは何年生まれ？', '昔、神様が動物たちに言った。
「1月1日の朝、わたしのうちへ早く来た順に、1番目から12番目のものに大切な仕事をあげよう。」
ネコは神様の話がよく聞こえなかったから、ネズミに「いつ？」と聞いた。ネズミは「2日だ」とうそを言った。
ウシが最初に神様のうちに着いたが、ウシの背中にはネズミがこっそり乗っていた。ドアが開いたときに、ネズミが飛び降りて、1番になった。そして2番から12番までの動物が決まった。
神様が言った。
「今年はネズミの年だ。ネズミの仕事は今年生まれる人たちを守ることだ。来年はウシ年で、ウシの仕事は来年生まれる人たちを守ることだ。毎年順番に仕事をして、12番まで仕事をしたら、またネズミの年になる。」
このときから毎年ネズミ年、ウシ年などと言う。ネコは遅れたから、仕事ももらえなかったし、ネコ年もない。それで、ネコはネズミを見ると、追いかける。今も怒っているのだ。', 'Ngày xửa ngày xưa, Thần linh nói với các loài động vật:
''Sáng ngày 1 tháng 1, theo thứ tự những ai đến nhà ta sớm nhất, ta sẽ giao công việc quan trọng cho 12 con đầu tiên.''
Mèo không nghe rõ lời Thần dặn nên hỏi Chuột: ''Khi nào thế?''. Chuột nói dối: ''Ngày mùng 2 đấy''.
Bò là con đầu tiên đến nhà Thần linh, nhưng trên lưng Bò có Chuột đã lén trèo lên. Khi cánh cửa mở ra, Chuột nhảy bổ xuống và về nhất. Thế là các con vật từ số 2 đến số 12 đã được quyết định.
Thần linh phán:
''Năm nay là năm Chuột. Việc của Chuột là bảo vệ những người sinh ra trong năm nay. Năm sau là năm Bò, việc của Bò là bảo vệ những người sinh ra năm sau. Mỗi năm lần lượt làm nhiệm vụ, khi hết 12 con thì lại đến năm Chuột.''
Từ dạo đó mới có năm Tý, năm Sửu v.v. Mèo vì đến muộn nên không nhận được nhiệm vụ, cũng chẳng có năm Mão (theo 12 con giáp Nhật Bản, năm Mão là Thỏ). Vì thế hễ nhìn thấy Chuột là Mèo đuổi bắt. Đến tận bây giờ Mèo vẫn còn tức giận.', '/media/reading/reading_n4_l31_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 31 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'あなたは何年生まれ？');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) どうしてネコはネズミを追いかけるのですか。', 'MULTIPLE_CHOICE', 'ネズミに「2日だ」とうそを教えられて遅れ、仕事ももらえずネコ年もなくなったため、今でも怒っているからです。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 31 AND rc.title = 'あなたは何年生まれ？' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, 'ネズミにうそをつかれて遅れ、十二支に入れなかったから', TRUE, 1 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 31 AND rc.title = 'あなたは何年生まれ？' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '神様のうちにネズミより先に着いたから', FALSE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 31 AND rc.title = 'あなたは何年生まれ？' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
