-- Reading Content: 桜とお花見
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '桜とお花見', '日本人に「いちばん好きな花は何ですか」と聞いたら、多くの人が「桜」と答えるでしょう。春になって桜が咲くと、周りの景色がみんなピンク色になります。本当にきれいです。そして、満開の桜は風が吹くと一斉に散ります。桜は散るときも、とてもきれいです。

春には、たくさんの人が桜を見に行きます。お花見は1200年ぐらいまえから続いている日本の春の大きいイベントです。桜が咲く時期は南から北へだんだん移ります。沖縄の桜がいちばん早くて、1月ごろ咲きます。北海道の桜は5月ごろ咲きます。ですから、お花見のシーズンになると、天気予報の中で、「上野公園の桜は来週金曜日ごろ満開になるでしょう。」とか、「弘前城の桜はもうすぐ咲くでしょう。」とか、桜の花が咲く日の予想を発表します。桜は1～2週間で散ってしまいますから、予想を聞いて、お花見の日を決めます。

お花見では、家族や友達と、桜を見ながら食べたり飲んだり、歌ったり踊ったりします。絵をかいたり、写真を撮ったりする人もいます。バーベキューなどができる公園もあります。昼の桜もいいですが、夜の桜もとてもきれいです。でも、お花見のころの夜はちょっと寒いかもしれませんから、セーターなど暖かい服を持って行ったほうがいいでしょう。

日本には、桜の名所がたくさんあります。春になると、桜の名所も、町の公園も、朝から夜まで人でいっぱいです。お花見は、日本人が短い桜の季節を楽しむ大切なイベントなのです。', 'Nếu hỏi người Nhật ''Bạn thích loài hoa nào nhất?'', có lẽ rất nhiều người sẽ trả lời là ''Hoa anh đào'' (Sakura). Khi mùa xuân đến và hoa anh đào nở, cảnh sắc xung quanh đều nhuộm một màu hồng. Thực sự rất đẹp. Và khi hoa nở rộ, chỉ một cơn gió thoảng qua là cánh hoa đồng loạt rơi rụng. Hoa anh đào ngay cả khi rụng cũng tuyệt đẹp.

Vào mùa xuân, rất nhiều người đi ngắm hoa. Ngắm hoa anh đào (Hanami) là một sự kiện lớn vào mùa xuân của Nhật Bản đã kéo dài khoảng 1200 năm nay. Thời điểm hoa anh đào nở dần dần dịch chuyển từ nam lên bắc. Hoa anh đào ở Okinawa nở sớm nhất vào khoảng tháng 1. Hoa anh đào ở Hokkaido nở vào khoảng tháng 5. Do đó khi bước vào mùa ngắm hoa, trong các bản tin dự báo thời tiết, người ta sẽ công bố dự báo ngày nở hoa như: ''Hoa anh đào ở công viên Ueno sẽ nở rộ vào khoảng thứ Sáu tuần sau'' hay ''Hoa anh đào ở thành Hirosaki sắp nở''. Vì hoa anh đào tàn rụng chỉ trong 1-2 tuần nên mọi người nghe dự báo để chọn ngày đi ngắm hoa.

Khi ngắm hoa, mọi người cùng gia đình, bạn bè vừa ngắm hoa vừa ăn uống, ca hát, nhảy múa. Có người vẽ tranh, chụp ảnh. Có những công viên cho phép nướng thịt BBQ. Hoa anh đào ban ngày đẹp nhưng hoa anh đào ban đêm cũng rất lung linh. Tuy nhiên ban đêm vào mùa ngắm hoa có thể hơi lạnh, nên mang theo áo ấm như áo len thì tốt hơn.

Ở Nhật Bản có rất nhiều danh lam thắng cảnh ngắm hoa anh đào nổi tiếng. Mùa xuân đến, từ các địa điểm nổi tiếng đến công viên trong phố đều chật kín người từ sáng đến tối. Ngắm hoa là một sự kiện quan trọng để người Nhật tận hưởng mùa hoa anh đào ngắn ngủi.', '/media/reading/reading_n4_l32_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '桜とお花見');
