INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '3) 天気予報を聞いてから、お花見の日を決めたほうがいいです。', 'MULTIPLE_CHOICE', '桜は1～2週間ですぐ散ってしまうため、天気予報の開花予想を聞いて日を決めるのが適切です。(〇)', NULL, 3 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND rc.title = '桜とお花見' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 3);
