-- Reading Content: お花見
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'お花見', '日本人3万人に桜とお花見について聞きました。

「桜が好きですか」という質問に対して：
・とても好き：75%
・まあまあ好き：22%
・どちらでもない：3%

好きなスタイル（スタイル別）：
① 昼、散歩しながら見る
② 夜桜を見る
③ 桜の木の下でパーティーをする
④ ドライブしながら見る
⑤ 会社や学校へ行くとき見る

また、桜の花や葉の塩漬けをお湯に入れて「桜茶」として飲んだり、桜の葉で包んだ「桜餅」や「鯛の桜蒸し」など、桜を料理や和菓子にして味わう文化もあります。', 'Khảo sát 30.000 người Nhật về hoa anh đào và việc ngắm hoa:

Đối với câu hỏi ''Bạn có thích hoa anh đào không?'':
- Rất thích: 75%
- Khá thích: 22%
- Bình thường/không ý kiến: 3%

Phong cách ngắm hoa được yêu thích:
① Ban ngày vừa đi dạo vừa ngắm
② Ngắm hoa anh đào ban đêm (Yozakura)
③ Mở tiệc liên hoan dưới gốc hoa anh đào
④ Vừa lái xe vừa ngắm
⑤ Ngắm trên đường đi làm hoặc đến trường

Ngoài ra còn có nét văn hóa thưởng thức ẩm thực từ hoa anh đào như ''Trà hoa anh đào'' (Sakura-cha), bánh ''Sakura-mochi'' hay món ''Cá tráp hấp hoa anh đào''.', '/media/reading/reading_n4_l32_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'お花見');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 日本人で桜が「とても好き」と答えた人は何％ですか。', 'MULTIPLE_CHOICE', '調査によると、「とても好き」と答えた人は75%です。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND rc.title = 'お花見' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '22%', FALSE, 1 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND rc.title = 'お花見' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '40%', FALSE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND rc.title = 'お花見' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '75%', TRUE, 3 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND rc.title = 'お花見' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 3);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '90%', FALSE, 4 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 32 AND rc.title = 'お花見' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 4);
-- =========================================================
-- BÀI 33 (2 bài đọc)
-- =========================================================
-- Reading Content: 大声大会
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '大声大会', 'わたしの町では毎年5月に大声大会があります。大きい声で何か叫んで、一年の嫌なことを忘れるのです。

去年のテーマは「あの人に言いたい」でした。ほとんどの人は「税金を下げろ！」とか「首相はやめろ！」とか叫びましたが、外国から参加した女の人は「トーホク！ ガ・ン・バ・ロー！」と叫びました。この声が大会でいちばん大きい声でした。大きい地震があった東北の人に「元気を出して。いっしょに頑張りましょう」と言いたかったのです。

ほかに、「山本！貸した金返せ！」「給料を上げろ！」「良子、結婚してくれ！」「社長、下手な英語を使うなー！」「幸子、かんにーん！」などがありました。「かんにん」は大阪弁で「すみません」という意味です。この人は何か幸子さんに謝りたいことがあるのでしょう。

毎日の生活では大声で叫ぶチャンスがありません。一年に一度、大声で叫んで、一年のストレスを全部出してしまいましょう。', 'Ở thị trấn của tôi, hàng năm vào tháng 5 đều tổ chức cuộc thi hét to. Mọi người hét to một điều gì đó để quên đi những chuyện không vui trong một năm.

Chủ đề năm ngoái là ''Điều muốn nói với người ấy''. Hầu hết mọi người đều hét lên: ''Hãy giảm thuế đi!'' hay ''Thủ tướng hãy từ chức đi!''. Nhưng một người phụ nữ nước ngoài tham gia đã hét: ''Tohoku! Cố lên nhé!''. Tiếng hét này là tiếng to nhất cuộc thi. Chị ấy muốn gửi lời đến người dân vùng Tohoku nơi vừa trải qua trận động đất lớn: ''Hãy lên tinh thần nhé. Cùng nhau cố gắng nào!''.

Ngoài ra còn có: ''Yamamoto! Trả tiền vay đây!'', ''Tăng lương đi!'', ''Yoshiko, lấy anh nhé!'', ''Giám đốc, đừng có nói tiếng Anh dở tệ nữa!'', ''Sachiko, tha lỗi cho anh!''. ''Kannin'' trong tiếng địa phương Osaka có nghĩa là ''Xin lỗi''. Chắc là anh này có điều gì muốn xin lỗi cô Sachiko.

Trong cuộc sống thường ngày chúng ta không có dịp hét to. Mỗi năm một lần, hãy hét thật to để giải tỏa hết căng thẳng trong một năm nhé.', '/media/reading/reading_n4_l33_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '大声大会');
