-- Reading Content: こんな人にこのことば
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'こんな人にこのことば', '日常生活の中で気をつけたいことと、ぴったりのことば：

・石川さん（25歳）：「禁煙？考えたことない。寝る前はベッドで吸うんだ。一度布団が少し燃えたことがあるけど。」
→「小さい火 初めはみんな 気をつけろ」

・上田さん（27歳）：「あ、あそこの信号、もうすぐ赤になる！早く渡ってしまおう。」
→「注意一秒、けが一生」

・南山さん（36歳）：「シーツを買いました。袋を開けてから自分のベッドで使えないとわかりました。店に返しに行ったけど換えてもらえませんでした。」
→「よく見て！聞いて！確かめて！」

・田村さん（53歳）：「ごみは多いですよ。エアコンは一年中使っています。車が好きだからどこでも車で行きます。」
→「守れ、緑の地球」

・高橋さん（42歳）：「おじいちゃんは最近何でも忘れるし、何回も聞くし疲れます。子どもはいくら言っても部屋を片づけないし。」
→「年寄り、笑うな、来た道だから。子ども、しかるな、行く道だから。」', 'Những thói quen cần lưu ý trong cuộc sống thường nhật và các câu nhắc nhở phù hợp:

- Anh Ishikawa (25 tuổi): ''Bỏ thuốc? Chưa từng nghĩ tới. Trước khi ngủ tôi hút trên giường. Đã có lần chăn bị cháy xém một chút rồi đấy.'' -> ''Lửa nhỏ lúc đầu, ai ai cũng phải cẩn thận.''

- Anh Ueda (27 tuổi): ''A, đèn giao thông sắp đỏ rồi! Mau sang đường thôi.'' -> ''Bất cẩn một giây, tàn tật một đời.''

- Chị Minamiyama (36 tuổi): ''Tôi mua ga trải giường. Mở túi ra mới biết không vừa giường nhà mình. Mang ra tiệm đổi thì không được đổi nữa.'' -> ''Hãy nhìn kỹ! Lắng nghe! Xác nhận kỹ!''

- Ông Tamura (53 tuổi): ''Rác nhiều lắm. Điều hòa bật quanh năm. Tôi thích xe nên đi đâu cũng lái ô tô.'' -> ''Hãy bảo vệ Trái Đất xanh.''

- Chị Takahashi (42 tuổi): ''Ông dạo này cái gì cũng quên, hỏi đi hỏi lại mệt ghê. Con cái thì bảo bao lần cũng không chịu dọn phòng.'' -> ''Người già chớ cười, vì đó là con đường ta từng đi qua. Trẻ nhỏ chớ mắng, vì đó là con đường ta sẽ đi tới.''', '/media/reading/reading_n4_l33_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'こんな人にこのことば');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 「ベッドでたばこを吸う人」に教えることばとして最も適切なものはどれですか。', 'MULTIPLE_CHOICE', '火災の危険があるため、「小さい火 初めはみんな 気をつけろ」が適切です。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND rc.title = 'こんな人にこのことば' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '注意一秒、けが一生', FALSE, 1 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND rc.title = 'こんな人にこのことば' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '小さい火 初めはみんな 気をつけろ', TRUE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND rc.title = 'こんな人にこのことば' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '守れ、緑の地球', FALSE, 3 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 33 AND rc.title = 'こんな人にこのことば' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 3);
