-- BÀI 34 (1 bài đọc)
-- =========================================================
-- Reading Content: あなたの国では？
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'あなたの国では？', '日本ではあいさつするとき、頭を下げます。握手をしたり体に触ったりするあいさつはあまりありません。また、日本人は「わたし」というとき、人差し指で自分の鼻を指します。

手を使うジェスチャーはいろいろあります。人の前や間を歩くとき、手を立てて上げたり下げたりします。これは「ちょっとすみません」という意味です。また、手を顔の前で横に何回も振ります。これは「さようなら」のジェスチャーではありません。「わかりません」「できません」「いいえ、違います」などの意味です。

人や犬などを呼ぶとき、日本人は手のひらを下に向けて振ります。また、日本人は口の前に人差し指を立てて「シーッ」と言います。これは「話すな！」という意味です。みんなの前で話すときは、ポケットに手を入れて話してはいけません。また、日本人は相手の目をあまり見ないで話します。じっと見ると失礼なのです。

このほかに笑うとき、手で口を隠す女の人がいます。昔、女の人はほかの人に歯を見せてはいけませんでした。それで今もその習慣のとおりにしているのです。

日本では小さい子どもに「いい子だね」と言うとき、頭に触ります。しかし、タイなどの東南アジアの国では頭に触ってはいけません。旅行のガイドブックにはタイへ行ったら、人の頭に触るなと書いてあります。世界にはいろいろなジェスチャーがあります。', 'Ở Nhật Bản khi chào hỏi, người ta cúi đầu. Rất ít khi bắt tay hay chạm vào cơ thể khi chào. Ngoài ra khi nói ''tôi'', người Nhật lấy ngón trỏ chỉ vào mũi mình.

Có rất nhiều cử chỉ điệu bộ (gesture) dùng tay. Khi đi cắt ngang mặt người khác hoặc đi giữa dòng người, họ giơ bàn tay khép thẳng lên xuống. Điệu bộ này có nghĩa là ''Xin lỗi một chút''. Khi xua tay ngang trước mặt nhiều lần, đây không phải cử chỉ tạm biệt, mà có nghĩa là ''Tôi không biết'', ''Tôi không làm được'' hoặc ''Không phải đâu''.

Khi gọi người hoặc gọi chó, người Nhật úp lòng bàn tay xuống dưới rồi vẫy. Ngoài ra người Nhật đặt ngón trỏ lên trước miệng và nói ''Suỵt'', có nghĩa là ''Đừng nói nữa!''. Khi nói chuyện trước đám đông, không được đút tay vào túi quần. Người Nhật cũng ít khi nhìn chằm chằm vào mắt đối phương khi nói chuyện vì nhìn chằm chằm là bất lịch sự.

Bên cạnh đó, khi cười có những phụ nữ lấy tay che miệng. Ngày xưa, phụ nữ không được để lộ răng cho người khác thấy. Vì thế cho đến nay họ vẫn duy trì tập quán đó.

Ở Nhật khi khen trẻ nhỏ ''Bé ngoan quá'', người ta xoa đầu bé. Tuy nhiên ở các nước Đông Nam Á như Thái Lan, tuyệt đối không được sờ vào đầu người khác. Sách hướng dẫn du lịch có viết nếu đến Thái Lan thì đừng chạm vào đầu người khác. Trên thế giới có muôn vàn cử chỉ điệu bộ khác nhau.', '/media/reading/reading_n4_l34_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'あなたの国では？');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 人がたくさんいる所で松本さんを呼びました。松本さんは「えっ、わたし？」と言いながら、どんなジェスチャーをしますか。', 'MULTIPLE_CHOICE', '日本人は「わたし」と言うとき、人差し指で自分の鼻を指します。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 34 AND rc.title = 'あなたの国では？' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
