INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '2) 販売機でたばこを買うときは、カードを販売機に入れる。', 'MULTIPLE_CHOICE', 'たばこは「タスポ」というカードを機械に「タッチ」しなければ買えないので、入れるのではありません。(✕)', NULL, 2 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND rc.title = '自動販売機' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 2);
