INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '3) 全部の販売機が使う電力は2013年までに75%減った。', 'MULTIPLE_CHOICE', '本文では「飲み物の販売機が使う電力は75%減った」とあり、全部の販売機ではありません。(✕)', NULL, 3 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND rc.title = '自動販売機' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 3);
