-- Reading Content: ほんとうに自動販売機で売っているの？
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'ほんとうに自動販売機で売っているの？', '日本にはいろいろ珍しい自動販売機もあります。

街で見かけるユニークな自動販売機の例：
・温かいおでんの缶詰
・きれいな生花
・突然の雨のための傘
・焼きたてのクレープやパン
・採れたての新鮮な卵や野菜

「こんな物まで売っているの？」と驚くような自動販売機がたくさん開発されています。', 'Ở Nhật Bản có rất nhiều loại máy bán hàng tự động độc đáo, lạ mắt.

Ví dụ những máy bán hàng kỳ lạ trên đường phố:
- Đồ hộp Oden nóng hổi
- Hoa tươi thơm ngát
- Ô dù đi mưa khi gặp mưa bất chợt
- Bánh crepe hoặc bánh mì nướng
- Trứng tươi và rau củ mới thu hoạch

Nhiều loại máy khiến người ta phải ngạc nhiên thốt lên: ''Đến món này mà cũng bán tự động ư?''.', '/media/reading/reading_n4_l35_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 35 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'ほんとうに自動販売機で売っているの？');
