-- =========================================================
-- BÀI 36 (1 bài đọc)
-- =========================================================
-- Reading Content: 動物の目
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '動物の目', '皆さんは動物園へ行ったことがあるでしょう？ 短い足や大きい耳、長い鼻など、動物の体の形は面白いですね。目の形や位置もいろいろです。どうしてシマウマの目は顔の横にあるのですか。ライオンの目は前にならんでいるのですか。皆さんは考えたことがありますか。

ライオンはほかの動物の肉を食べます。その目は、遠くに動物がいても、すぐ走って行って捕まえられるように顔の前に2つ並んでいます。2つ並んでいなければ、正しい距離がわかりません。サルの目も顔の前に並んでいます。サルは木から木へ跳ぶとき、失敗しないように、よく前を見なければなりません。ヒトの目も同じです。ヒトは2本の足で歩けるようになって、手が使えるようになりました。それで、手で難しい仕事ができます。

草や木の葉を食べる動物の目はどうですか。シマウマはライオンなどにいつも気をつけていなければなりません。ですから、草を食べていても、うしろの方まで見えるように、目が顔の横に付いています。カバは水の中にいますが、頭の上に目がありますから、目だけ水から出して周りを見ることができます。

動物の目は食べる物や住んでいる所によって違うのです。今度動物園へ行ったら、動物の目をよく見てください。面白いことが見つかるかもしれませんよ。', 'Chắc hẳn mọi người từng đi vườn thú rồi nhỉ? Chân ngắn, tai to, mũi dài... hình dáng cơ thể các loài động vật thật thú vị. Hình dáng và vị trí của đôi mắt cũng rất đa dạng. Tại sao mắt ngựa vằn lại nằm ở hai bên mặt? Tại sao mắt sư tử lại cùng nằm ở phía trước? Mọi người đã từng nghĩ về điều đó chưa?

Sư tử ăn thịt các loài động vật khác. Mắt của chúng nằm song song phía trước khuôn mặt để dù con mồi ở xa cũng có thể lao tới vồ bắt chính xác khoảng cách. Nếu hai mắt không cùng hướng về phía trước thì không thể xác định chính xác cự ly. Mắt khỉ cũng nằm ở phía trước mặt. Khi khỉ chuyền từ cành cây này sang cành cây khác, để không bị ngã trượt, chúng phải nhìn rõ phía trước. Mắt con người cũng vậy. Con người đi bằng hai chân nên đôi tay được giải phóng và có thể làm những công việc khéo léo, phức tạp.

Còn mắt của loài ăn cỏ lá cây thì sao? Ngựa vằn luôn phải cảnh giác trước sư tử. Vì vậy, ngay cả khi đang cúi đầu gặm cỏ, để có thể nhìn thấy cả phía sau, mắt của chúng nằm ở hai bên mặt. Hà mã sống dưới nước, nhưng mắt nằm trên đỉnh đầu nên chúng có thể chỉ nhô mắt lên khỏi mặt nước để quan sát xung quanh.

Mắt của động vật khác nhau tùy thuộc vào thức ăn và nơi sinh sống của chúng. Lần tới đi sở thú, các bạn hãy quan sát thật kỹ đôi mắt của các con vật nhé. Có thể bạn sẽ phát hiện ra nhiều điều thú vị đấy.', '/media/reading/reading_n4_l36_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 36 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '動物の目');
