-- =========================================================
-- BÀI 38 (3 bài đọc)
-- =========================================================
-- Reading Content: 消したいもの
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '消したいもの', '「あなたが一番消したいものは何ですか。」
ある会社が1000人にアンケートをしました。

大人の男性と女性が消したいもの：
・1番：体の脂肪
・2番：借りたお金
・3番：恥ずかしいこと
男の人は「借りたお金」と答えた人が多くて、女の人は「体の脂肪」と答えた人が多かったです。

子どもの消したいもの：
・1番：悪い成績
・2番：宿題
・3番：けんかしたこと

アンケートをした会社は、消しゴムを作っている会社です。「何でも消せる消しゴムがあればいいですね」と社長は言いました。', '''Điều bạn muốn xóa đi nhất là gì?''
Một công ty đã làm cuộc khảo sát với 1.000 người.

Điều người lớn (nam và nữ) muốn xóa đi nhất:
- Số 1: Lượng mỡ thừa trên cơ thể
- Số 2: Tiền vay nợ
- Số 3: Những chuyện đáng xấu hổ trong quá khứ
Ở nam giới người trả lời là ''tiền vay nợ'' chiếm nhiều nhất, còn ở nữ giới người trả lời là ''mỡ thừa'' chiếm nhiều nhất.

Điều trẻ em muốn xóa đi nhất:
- Số 1: Điểm số kém
- Số 2: Bài tập về nhà
- Số 3: Những lần cãi vã đánh nhau với bạn bè

Công ty làm cuộc khảo sát này chính là một công ty chuyên sản xuất tẩy (gôm). Vị giám đốc nói: ''Giá như có một cục tẩy xóa được mọi thứ trên đời thì hay biết mấy''.', '/media/reading/reading_n4_l38_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '消したいもの');
