-- Reading Content: なぞなぞ
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'なぞなぞ', '日本の面白いなぞなぞ：

1. 切っても、切っても、切れないものは何？
→ こたえ：水（みず）

2. 生まれると、みんながもらうもの。自分のものだけど、ほかの人がよく使うものは何？
→ こたえ：名前（なまえ）

3. 作った人は言わない、持っている人はわからない、知っている人は欲しくないものは何？
→ こたえ：にせ金（にせがね）

4. 長生きすると多くなるけど、欲しくないものは何？
→ こたえ：年（とし）／しわ

5. 眠くなると会いに来て、起きるといない。見たくてもなかなか見られないものは何？
→ こたえ：夢（ゆめ）', 'Những câu đố mẹo dân gian thú vị của Nhật Bản:

1. Càng cắt càng không đứt là gì?
-> Đáp án: Nước.

2. Sinh ra ai cũng được nhận. Là của mình nhưng người khác lại dùng nhiều nhất?
-> Đáp án: Tên gọi.

3. Người làm ra không nói, người cầm không hay, người biết rõ thì chẳng ai muốn nhận?
-> Đáp án: Tiền giả.

4. Càng sống lâu thì càng nhiều thêm, nhưng chẳng ai muốn nhận thêm là gì?
-> Đáp án: Tuổi tác / nếp nhăn.

5. Khi buồn ngủ thì tìm đến, khi tỉnh giấc thì biến mất, muốn nhìn thấy cũng khó là gì?
-> Đáp án: Giấc mơ.', NULL, 3 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 38 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'なぞなぞ');
