-- Reading Content: 万次郎
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '万次郎', '1827年、高知の小さな村に元気な男の子が生まれました。名前は万次郎。家族は魚をとって暮らしていました。9歳のときにお父さんが亡くなったので、万次郎は家族のために、働かなければなりませんでした。

1841年、14歳の万次郎は4人の仲間と船で漁に出ましたが、嵐に遭って太平洋の無人島に流されました。水も食べ物もほとんどない島で143日間生き延びた後、アメリカの捕鯨船「ジョン・ハウランド号」に助けられました。船長のホイットフィールドは万次郎の頭の良さと人柄を気に入り、アメリカへ連れて行きました。万次郎は「ジョン・マン」と呼ばれ、アメリカの学校で英語、数学、測量、航海術などを熱心に勉強しました。

その後、万次郎は故郷の日本へ帰ることを決意し、1851年に日本へ戻りました。当時、日本は鎖国をしていましたが、ペリーの黒船が来航すると、幕府は英語と航海術に通じた万次郎を必要とし、武士の身分を与えて「中浜万次郎」と名乗らせました。万次郎は通訳や翻訳、航海術の教授として、日本の近代化に大きく貢献しました。', 'Năm 1827, tại một ngôi làng nhỏ ở Kochi, một bé trai khôi ngô ra đời. Tên cậu là Manjiro. Gia đình sống bằng nghề đánh cá. Năm 9 tuổi cha mất, Manjiro phải bươn chải làm việc để phụ giúp gia đình.

Năm 1841, Manjiro 14 tuổi cùng 4 người bạn đi thuyền đánh cá thì gặp bão lớn dạt vào một hoang đảo ở Thái Bình Dương. Sau 143 ngày sinh tồn khắc nghiệt trên hòn đảo thiếu nước và đồ ăn, họ được tàu săn cá voi Mỹ mang tên ''John Howland'' cứu sống. Thuyền trưởng Whitfield rất quý mến sự thông minh và hoạt bát của Manjiro nên đã đưa cậu về Mỹ. Manjiro được gọi thân mật là ''John Mung'', cậu chăm chỉ học tiếng Anh, toán học, trắc địa và kỹ thuật hàng hải tại trường học ở Mỹ.

Sau đó, Manjiro quyết tâm trở về quê hương Nhật Bản và đã trở về vào năm 1851. Thời điểm đó Nhật Bản đang bế quan tỏa cảng, nhưng khi tàu đen của Đề đốc Perry cập bến, chính quyền Mạc phủ rất cần người thông thạo tiếng Anh và hàng hải nên đã phong cho Manjiro thân phận võ sĩ Samurai với họ tên Nakahama Manjiro. Manjiro đã đảm nhận phiên dịch, dịch thuật, giảng dạy kỹ thuật đi biển và đóng góp to lớn cho công cuộc hiện đại hóa của Nhật Bản.', '/media/reading/reading_n4_l39_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '万次郎');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 万次郎が無人島に流されたあと、だれに助けられましたか。', 'MULTIPLE_CHOICE', 'アメリカの捕鯨船（ジョン・ハウランド号）に助けられました。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND rc.title = '万次郎' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
