-- Reading Content: 読みましたか・見ましたか・聞きましたか
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '読みましたか・見ましたか・聞きましたか', '心に残る名作や文化の紹介：

1. 本文の「万次郎」を読みましたか。すごい運命の人がいたんですね。
2. 「鉄腕アトム」を知っていますか。マンガも面白いけど、アニメもいいですね。テーマ曲を聞くと元気が湧いてきます。
3. バレエを見たことがありますか。「白鳥の湖」で白鳥を踊った人はとてもきれいで感動しました。
4. 映画や演劇の「シラノ・ド・ベルジュラック」を見て感動しました。本当の愛を伝える名作です。', 'Giới thiệu những tác phẩm văn hóa nghệ thuật lay động lòng người:

1. Bạn đã đọc câu chuyện về ''Manjiro'' chưa? Đúng là một con người với số phận kỳ diệu nhỉ.
2. Bạn có biết ''Astro Boy'' (Atom tay sắt) không? Truyện tranh hay mà hoạt hình cũng tuyệt. Cứ nghe nhạc mở đầu là thấy tràn đầy năng lượng.
3. Bạn từng xem múa ba lê chưa? Xem ''Hồ thiên nga'', vũ công múa vai thiên nga đẹp tuyệt trần khiến người xem xúc động.
4. Xem vở kịch ''Cyrano de Bergerac'' thật xúc động. Một kiệt tác về tình yêu chân thành.', '/media/reading/reading_n4_l39_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '読みましたか・見ましたか・聞きましたか');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 「鉄腕アトム」のテーマ曲を聞くとどんな気持ちになると紹介されていますか。', 'MULTIPLE_CHOICE', 'アトムの歌を聞くと元気が出ると書かれています。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 39 AND rc.title = '読みましたか・見ましたか・聞きましたか' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
