-- Reading Content: 常識
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '常識', 'わたしのうちに今、ブラジルのアナさんがホームステイしています。アナさんがかぜをひいたとき、母は「シャワーを浴びたり、おふろに入ったりしたらだめよ」と言いました。アナさんは「どうしていけないか、わかりません。病気のときは清潔が大切だし、わたしのうちでは熱が下がるようにシャワーを浴びたり、ぬるいお湯に入ったりします」と言いました。

それを聞いて、わたしたちはびっくりしました。熱があったり、かぜをひいたりしているときは、おふろに入らないほうがいいと信じていたからです。学校で友達に聞いてみましたが、みんな「おふろは入らないほうがいいと思う」と言いました。どうしてでしょうか。昔の日本のおふろは外にあったり、脱衣所が寒かったりして湯冷めしやすかったからです。でも今の日本の家は暖房があって暖かいので、さっとシャワーを浴びるくらいなら問題ありません。

生活が変わっても、昔の常識をそのまま信じているのは不思議です。ときどきその常識が正しいかどうか、どうしてその常識ができたのか、考えてみたほうがいいでしょう。', 'Nhà tôi hiện có bạn Ana đến từ Brazil đang ở homestay. Khi Ana bị cảm cúm, mẹ tôi dặn: ''Đừng tắm vòi sen hay ngâm bồn tắm con nhé''. Ana ngạc nhiên bảo: ''Cháu không hiểu tại sao lại không được ạ. Khi ốm thì giữ vệ sinh sạch sẽ rất quan trọng, ở nhà cháu khi bị sốt mọi người thường tắm vòi sen hoặc ngâm nước ấm vừa phải để hạ sốt ạ''.

Nghe vậy chúng tôi rất ngạc nhiên. Bởi vì người Nhật từ xưa luôn tin rằng khi sốt hay cảm cúm thì không nên tắm. Tôi hỏi bạn bè ở trường, ai cũng nói ''Tớ nghĩ không nên tắm''. Tại sao lại như vậy? Vì ngày xưa phòng tắm ở Nhật thường nằm ngoài trời hoặc phòng thay đồ rất lạnh nên rất dễ bị nhiễm lạnh sau khi tắm. Nhưng nhà cửa ngày nay có hệ thống sưởi ấm áp, nên tắm nhanh dưới vòi sen thì không có vấn đề gì.

Dù đời sống đã thay đổi nhưng vẫn mù quáng tin vào những ''thường thức'' ngày xưa thì thật kỳ lạ. Thỉnh thoảng chúng ta nên suy ngẫm xem thường thức đó có còn đúng hay không, và vì sao lại có định kiến thường thức ấy.', '/media/reading/reading_n4_l40_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 40 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '常識');
