-- Reading Content: ロボットといっしょ
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'ロボットといっしょ', '日本は「ロボット大国」と言われています。工場で自動車や精密機械を作る産業用ロボットだけでなく、最近では病院や介護施設、そして家庭でも様々なロボットが活躍しています。

お年寄りの介護の現場では、ベッドから車いすへ人を持ち上げる介護ロボットや、いっしょに体操をしてくれる体操ロボットが導入されています。また、本物のアザラシの赤ちゃんそっくりの「癒やしロボット（パロ）」は、名前を呼ぶと甘えた声を出し、触ると気持ちよさそうに目を閉じます。認知症のお年寄りがパロと触れ合うことで、笑顔が増え、心が落ち着く効果が認められています。

さらに、掃除ロボットや案内ロボット、会話ができるコミュニケーションロボットなど、私たちの暮らしの身近なパートナーとしてロボットは日々進化しています。少子高齢化が進む日本において、ロボットはなくてはならない存在になりつつあります。', 'Nhật Bản được mệnh danh là ''Cường quốc robot''. Không chỉ những robot công nghiệp chế tạo ô tô hay máy móc chính xác trong nhà máy, mà gần đây trong bệnh viện, viện dưỡng lão và ngay cả các hộ gia đình, nhiều loại robot đa dạng cũng đang phát huy vai trò lớn.

Tại các cơ sở chăm sóc người cao tuổi, robot nâng đỡ người từ giường sang xe lăn hay robot tập thể dục cùng các cụ đã được đưa vào sử dụng. Đặc biệt, chú robot hải cẩu con ''Paro'' giống hệt thật, khi được gọi tên sẽ phát ra tiếng kêu nũng nịu, khi được vuốt ve sẽ lim dim mắt khoan khoái. Người già suy giảm trí nhớ khi tiếp xúc với Paro đã cười nhiều hơn và tinh thần trở nên bình an hơn.

Ngoài ra, robot hút bụi, robot lễ tân hướng dẫn, robot giao tiếp... đang không ngừng phát triển như những người bạn đồng hành thân thiết. Trong một xã hội già hóa và sinh ít như Nhật Bản, robot đang dần trở thành sự tồn tại không thể thiếu.', '/media/reading/reading_n4_l41_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'ロボットといっしょ');
