INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '2) アザラシのロボット（パロ）はおしゃべりができる。', 'MULTIPLE_CHOICE', 'パロは鳴き声を出したり目を閉じたりして癒やすロボットであり、人間の言葉でおしゃべりをするわけではありません。(✕)', NULL, 2 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 41 AND rc.title = 'ロボットといっしょ' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 2);
