-- BÀI 42 (3 bài đọc)
-- =========================================================
-- Reading Content: 肉を食べると
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '肉を食べると', '世界中の人が食べる肉の量は毎年増えている。その大きな原因は人々の食生活が変わったからだ。日本でも魚や野菜より肉が好きな子どもが多い。

今、世界では牛や羊、豚、鶏など、たくさんの家畜が飼われている。家畜の数は世界の人口の3倍以上で、今も増えている。増えた牛や羊を飼うのに、新しい草地が必要になる。それで、草地を作るために、世界中の森の木が切られている。森が少なくなると、二酸化炭素が増えて地球は暖かくなる。そして、草地はだんだん砂漠化する。

また、家畜のえさに麦やとうもろこしなどたくさんの穀物が使われる。牛の肉1キロを作るのに、約11キロもの穀物と大量の水やエネルギーが必要になる。私たちが肉をたくさん食べることは、地球の環境や食料問題と深くつながっているのだ。', 'Lượng thịt con người tiêu thụ trên thế giới đang tăng lên mỗi năm. Nguyên nhân chính là do thói quen ăn uống của mọi người đã thay đổi. Ngay cả ở Nhật Bản, trẻ em thích ăn thịt hơn cá và rau củ cũng ngày một nhiều.

Hiện nay, trên thế giới có rất nhiều gia súc gia cầm như bò, cừu, lợn, gà được chăn nuôi. Số lượng gia súc gấp hơn 3 lần dân số toàn cầu và vẫn tiếp tục tăng. Để chăn thả lượng bò và cừu tăng lên đó, cần thêm nhiều đồng cỏ mới. Vì thế, để lấy đất làm đồng cỏ, rừng trên khắp thế giới đang bị chặt phá. Rừng suy giảm khiến khí CO2 tăng cao và Trái Đất nóng lên. Những bãi chăn thả dần dần bị sa mạc hóa.

Ngoài ra, một lượng khổng lồ ngũ cốc như lúa mì, ngô được dùng làm thức ăn gia súc. Để sản xuất được 1 kg thịt bò cần tới khoảng 11 kg ngũ cốc cùng một lượng nước và năng lượng khổng lồ. Việc chúng ta ăn nhiều thịt có mối liên hệ mật thiết đến môi trường và an ninh lương thực của Trái Đất.', '/media/reading/reading_n4_l42_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '肉を食べると');
