-- Reading Content: 地球はどうなる？
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '地球はどうなる？', '環境問題の原因と結果：

・ごみを分別せず何でも燃やす
→ ダイオキシンが出る → 体が弱くなる、環境ホルモンの影響

・エネルギーを大量に使い、物を使い捨てる
→ 二酸化炭素（CO2）が増える → 地球温暖化が進む → 気候変動、食料不足、難民の発生

・古い電化製品を適切に処理せず壊す
→ フロンガスが出る → オゾン層が破壊される → 紫外線が増加する → 皮膚ガンや病気が増える', 'Nguyên nhân và hậu quả của các vấn đề môi trường:

- Không phân loại rác, đốt rác bừa bãi:
-> Sản sinh khí Dioxin độc hại -> Sức khỏe suy giảm, ảnh hưởng hormone môi trường.

- Sử dụng lãng phí năng lượng, xả rác dùng một lần:
-> Khí CO2 tăng -> Trái Đất ấm lên -> Biến đổi khí hậu, khủng hoảng lương thực.

- Thải bỏ sai quy cách các thiết bị điện tử cũ:
-> Rò rỉ khí Freon -> Phá hủy tầng Ozon -> Tia cực tím gia tăng -> Nguy cơ ung thư da và bệnh tật.', '/media/reading/reading_n4_l42_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '地球はどうなる？');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 地球温暖化（地球が暖かくなること）の直接の原因となる気体は何ですか。', 'MULTIPLE_CHOICE', '二酸化炭素（CO2）が増えることが地球温暖化の大きな原因です。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 42 AND rc.title = '地球はどうなる？' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
