-- Reading Content: カレー
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'カレー', 'カレーライスを食べたことがありますか。カレーはもともとインドの料理ですが、日本には明治時代にイギリスから伝わりました。

日本人はインドのカレーの作り方をイギリス人から学び、自分たちの好みに合うように工夫しました。小麦粉を入れてとろみをつけ、ご飯の上にかけて食べる「カレーライス」が誕生したのです。明治時代の終わりにはカレールウが国産化され、安くて栄養がある料理として全国の家庭や軍隊、学校給食に広まりました。

昭和30年代（1950年代）に固形の「即席カレールウ」が発売されると、家庭で手軽にカレーが作れるようになり、生産量は飛躍的に増えました。今ではカレーうどん、カレー南蛮、カレーパンなど、カレーを使った日本独自の料理がたくさんあります。あるインド人は日本でカレールウを買って「日本のカレーは辛すぎずとても美味しい」と喜んで国へ持ち帰ったそうです。今や日本のカレーは独自の日本料理と言ってもいいでしょう。', 'Bạn đã từng ăn cơm cà ri (Curry rice) chưa? Cà ri vốn có nguồn gốc từ Ấn Độ, nhưng du nhập vào Nhật Bản từ nước Anh vào thời kỳ Minh Trị.

Người Nhật đã học cách nấu cà ri của người Ấn thông qua người Anh, rồi biến tấu sao cho phù hợp với khẩu vị của mình. Họ thêm bột mì để tạo độ sánh sệt, rồi rưới lên cơm nóng ăn kèm - món cơm cà ri đặc trưng ra đời từ đó. Cuối thời Minh Trị, viên gia vị cà ri roux được tự sản xuất trong nước, trở thành món ăn vừa ngon, bổ dưỡng lại rẻ tiền nên đã phổ biến khắp các gia đình, quân đội và bữa ăn bán trú học đường.

Vào những năm 1950 (thập niên Chiêu Hòa 30), khi viên cà ri cô đặc ăn liền ra đời, các gia đình có thể nấu cà ri dễ dàng, sản lượng tiêu thụ tăng vọt gấp nhiều lần. Ngày nay có rất nhiều món ăn độc đáo của Nhật sử dụng cà ri như mì udon cà ri, bánh mì nhân cà ri... Có một người Ấn Độ sau khi mua cà ri Nhật đã khen rằng ''Cà ri Nhật không quá cay nồng mà vị rất thanh ngon'' và mang về nước làm quà. Giờ đây cà ri Nhật hoàn toàn có thể được xem là một nét ẩm thực mang bản sắc riêng của Nhật Bản.', '/media/reading/reading_n4_l44_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'カレー');
