-- Reading Content: 料理教室
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '料理教室', 'きょうは「お好み焼き」を作ってみましょう！

【材料（4人分）】
小麦粉 2カップ、水 1カップ、卵 2個、キャベツ 1/2個、豚肉やエビなど 100g、お好み焼きソース、かつおぶし、青のり、塩 少々

【作り方】
1. 小麦粉に、水と卵と塩を入れて混ぜる。よく混ざったら、小さく刻んだキャベツを入れてもう一度さっくり混ぜる。
2. フライパンを熱して油を薄くひき、生地を入れて丸く広げる。厚さは2センチくらいにする。厚すぎると中まで火が通らない。
3. 豚肉やエビなど好みの具を上にきれいに載せる。
4. 下側と周りが焼けたら、裏返す。火が強すぎると焦げやすいので注意する。
5. 両面がしっかり焼けたら、ソースを塗り、かつおぶしと青のりをふりかけて完成！', 'Hôm nay chúng ta cùng vào bếp làm món bánh xèo Nhật Bản ''Okonomiyaki'' nhé!

[Nguyên liệu (khẩu phần 4 người)]
Bột mì 2 cốc, nước 1 cốc, trứng gà 2 quả, bắp cải 1/2 cái, thịt lợn hoặc tôm 100g, xốt okonomiyaki, cá bào katsuobushi, rong biển sợi aonori, một chút muối.

[Cách làm]
1. Cho bột mì, nước, trứng và chút muối vào âu trộn đều. Khi bột đã đều, cho bắp cải thái nhỏ vào trộn đều nhẹ tay.
2. Làm nóng chảo, thoa một lớp dầu mỏng, trút bột vào dàn đều thành hình tròn dày khoảng 2 cm. Nếu quá dày bánh sẽ khó chín bên trong.
3. Xếp thịt lợn hoặc tôm lên mặt trên của bánh.
4. Khi mặt dưới và viền bánh đã chín vàng giòn thì lật mặt bánh. Chú ý lửa vừa để không bị cháy.
5. Khi hai mặt đều chín vàng thơm, quét đều xốt okonomiyaki, rắc cá bào và rong biển lên trên rồi thưởng thức!', '/media/reading/reading_n4_l44_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '料理教室');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) お好み焼きを焼くとき、生地の厚さはどのくらいが適していますか。', 'MULTIPLE_CHOICE', '厚すぎると中まで火が通らないため、約2センチが適しています。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 44 AND rc.title = '料理教室' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
