-- Reading Content: いとこの長靴
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'いとこの長靴', '僕は3歳のとき、パトカーに乗ったことがある。雨の降る日、僕は年上のいとこの大きな赤い長靴をはいて、散歩に出かけた。ぶかぶかの長靴は歩きにくかったが、水たまりを踏むのが楽しくて、夢中で歩いているうちに迷子になってしまったのだ。

気がついたときは知らない大通りで、泣きべそをかいていた僕を、通りかかったパトカーのお巡りさんが助けてくれた。交番へ連れて行かれ、優しいお巡りさんがクリームパンとジュースを買ってくれた。僕は泣くのをやめて、美味しそうにパンを食べていた。

そこへ血相を変えた両親が駆け込んできた。警察官にお礼を言いながら、母は僕を強く抱きしめて泣いた。僕は口の周りにクリームをつけたまま、何が起こったのかよくわからずにいたが、あの赤い長靴とパトカーのサイレンの音は、今でも鮮明に覚えている。', 'Năm lên 3 tuổi, tôi từng được ngồi trên xe cảnh sát một lần. Vào một ngày mưa, tôi xỏ đôi ủng đỏ to đùng của người anh họ rồi ra ngoài dạo chơi. Đôi ủng rộng thùng thình bước đi thật khó, nhưng nhảy vào các vũng nước mưa thích quá nên mải mê đi một hồi tôi bị lạc lúc nào không hay.

Đến khi nhận ra mình đang ở trên đại lộ xa lạ, tôi bắt đầu mếu máo khóc thì được các chú cảnh sát trên xe tuần tra đi ngang qua cứu giúp. Được đưa về bốt cảnh sát (Koban), các chú cảnh sát tốt bụng mua cho tôi một chiếc bánh mì nhân kem và hộp nước hoa quả. Tôi nín khóc và ngon lành gặm chiếc bánh mì.

Đúng lúc đó, bố mẹ tôi mặt mày tái mét hớt hải chạy vào. Vừa rối rít cảm ơn các anh cảnh sát, mẹ vừa ôm chầm lấy tôi bật khóc nức nở. Tôi với miệng còn dính đầy kem trắng xóa, ngơ ngác chẳng hiểu chuyện gì lớn, nhưng đôi ủng đỏ và âm thanh còi xe tuần tra ngày ấy đến giờ tôi vẫn nhớ như in.', '/media/reading/reading_n4_l46_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'いとこの長靴');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) ぼくは3歳のとき、パトカーに乗ったことがある。', 'MULTIPLE_CHOICE', '迷子になったときパトカーに乗せてもらいました。(〇)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND rc.title = 'いとこの長靴' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '〇', TRUE, 1 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND rc.title = 'いとこの長靴' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 1);
