INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '2) ぼくが迷子になった原因は何ですか。', 'MULTIPLE_CHOICE', 'いとこの大きな長靴をはいて水たまりで遊んでいるうちに夢中になって道に迷いました。', NULL, 2 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND rc.title = 'いとこの長靴' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 2);
