INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '友達とけんかして家出をしたから', FALSE, 4 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND rc.title = 'いとこの長靴' AND rq.sort_order = 2 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 4);
-- Reading Content: 俳句
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '俳句', '俳句は日本で生まれた世界でいちばん短い、17音の詩です。

俳句を作るときの基本的な規則：
1. 17音を「五・七・五」のリズムにして作る。
2. 季節を表すことば「季語（きご）」を入れる。
3. 気持ちを強調したりリズムを整えたりするために「や」「かな」「けり」などの切れ字を使う。

【有名な日本の俳句】
・春：菜の花や 月は東に 日は西に（与謝蕪村）
菜の花が一面に咲く夕暮れ時、東の空に月が昇り、西の空に太陽が沈んでいく壮大な春の風景です。

・夏：閑さや 岩にしみ入る 蝉の声（松尾芭蕉）
山寺の静けさの中、蝉の鳴き声だけが岩にしみ通るように響く、深閑とした夏の情景です。

・秋：名月を 取ってくれろと 泣く子かな（小林一茶）
秋の美しい満月を見て、「あのお月様を取って！」と無心にねだる幼い子どもの愛らしい姿を詠んでいます。', 'Haiku là thể thơ ngắn nhất thế giới gồm 17 âm tiết, ra đời tại Nhật Bản.

Quy tắc cơ bản khi làm thơ Haiku:
1. 17 âm tiết được ngắt theo nhịp 5 - 7 - 5.
2. Bắt buộc có ''Kigo'' (từ chỉ mùa).
3. Sử dụng từ ngắt câu như ''ya'', ''kana'' để nhấn mạnh cảm xúc và tạo nhịp điệu.

[Những bài thơ Haiku nổi tiếng]:
- Mùa xuân: ''Cánh đồng hoa cải vàng / Trăng lên đầu non đông / Vầng dương lặn hướng tây'' (Yosa Buson).
- Mùa hạ: ''Vắng lặng biết bao lăm / Tiếng ve ngâm rả rích / Thấm sâu vào lòng đá'' (Matsuo Basho).
- Mùa thu: ''Vằng vặc ánh trăng rằm / Đứa bé nheo nhẻo khóc / Đòi hái vầng trăng chơi'' (Kobayashi Issa).', '/media/reading/reading_n4_l46_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '俳句');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 俳句の音の数とリズムとして正しいものはどれですか。', 'MULTIPLE_CHOICE', '俳句は「五・七・五」の17音で作られます。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 46 AND rc.title = '俳句' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
