-- =========================================================
-- BÀI 47 (2 bài đọc)
-- =========================================================
-- Reading Content: 空を飛ぶ自動車
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '空を飛ぶ自動車', '空を飛ぶ自動車が欲しいと思ったことはありませんか。SFマンガや映画の中で見たことがある人も多いでしょう。実は、本当に空を飛べる自動車「スカイカー」の開発が世界中で進んでいます。

アメリカのあるベンチャー企業が2012年に発表したスカイカーは、翼を広げると飛行機になり、翼を畳むと普通の道路を走ることができます。ただし、離陸するためには約760メートルの滑走路が必要でした。価格は約2300万円でしたが、100人以上が予約したそうです。

さらに最近では、滑走路が不要でヘリコプターのように垂直に離着陸できるハイブリッド型スカイカー（eVTOL）も開発されています。これが実用化されれば、交通渋滞を避けて都市間を高速で移動できるようになり、離島や山間部への移動も格段に便利になると期待されています。', 'Bạn đã bao giờ ao ước có một chiếc ô tô bay trên bầu trời chưa? Chắc hẳn nhiều người từng thấy phương tiện này trong truyện tranh hay phim viễn tưởng. Thực ra, dự án phát triển ô tô bay ''Sky car'' đang được tiến hành rầm rộ khắp nơi trên thế giới.

Một công ty khởi nghiệp ở Mỹ vào năm 2012 đã giới thiệu mẫu Sky car khi giương cánh thì biến thành máy bay, còn khi gập cánh lại có thể chạy trên làn đường ô tô bình thường. Tuy nhiên khi cất cánh cần đường băng dài khoảng 760 mét. Mức giá khoảng 23 triệu Yên nhưng đã có hơn 100 người đặt trước.

Gần đây hơn, các mẫu ô tô bay cất hạ cánh thẳng đứng (eVTOL) không cần đường băng như trực thăng đang được hoàn thiện. Khi được đưa vào thương mại hóa, con người có thể tránh được nạn tắc đường, di chuyển giữa các thành phố với tốc độ cao, đồng thời việc đi lại tới các hải đảo và vùng núi hẻo lánh sẽ thuận tiện vượt bậc.', '/media/reading/reading_n4_l47_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '空を飛ぶ自動車');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 2012年に発表されたスカイカーは、渋滞した道路からその場ですぐ垂直に空へ飛び立つことができた。', 'MULTIPLE_CHOICE', '2012年のスカイカーは離陸に約760mの滑走路が必要でした。(✕)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND rc.title = '空を飛ぶ自動車' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
