-- Reading Content: ほんとうにあるのは？
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'ほんとうにあるのは？', '未来の便利グッズあれこれ：

1. 《元気になるズボン（歩行アシストスーツ）》
高齢者や足の不自由な人が履くと、モーターの力で足が軽くなり、楽に歩けるようになるスーツ。→【実在する】

2. 《目薬コンタクトレンズ》
朝、目薬を1滴さすだけで一日中視力が回復し、夜目を洗えば元に戻る薬。→【実在しない・研究中】

3. 《クレジットカードになる腕時計（スマートウォッチ）》
時計を改札やレジの機械にかざすだけで支払いができる。→【実在する】

4. 《折り畳み式の橋（緊急架橋車）》
地震や台風で橋が流されたとき、わずか10分で伸びて川に架けられる頑丈な橋。→【実在する】', 'Những phát minh tiện ích thú vị:

1. ''Quần tiếp thêm sinh lực'' (Bộ đồ hỗ trợ vận động): Người già hoặc người khó khăn đi lại khi mặc vào, động cơ hỗ trợ nâng đỡ chân bước đi nhẹ nhàng thoăn thoắt. -> [Có thật]
2. ''Thuốc nhỏ mắt kính áp tròng'': Sáng nhỏ 1 giọt là mắt sáng cả ngày, tối rửa mắt là hết. -> [Chưa có thật / Đang nghiên cứu]
3. ''Đồng hồ thanh toán thông minh'': Chỉ cần đưa cổ tay chạm vào máy là thanh toán xong vé tàu hay hóa đơn mua sắm. -> [Có thật]
4. ''Cầu gấp thông minh'': Khi cầu bị sập do bão lũ động đất, xe chuyên dụng chỉ mất 10 phút là có thể bắc xong cây cầu kiên cố vượt sông. -> [Có thật]', '/media/reading/reading_n4_l47_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'ほんとうにあるのは？');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 紹介されている発明の中で、災害時に川に架けて使える折り畳み式の橋は実在しますか。', 'MULTIPLE_CHOICE', '地震や水害時の緊急救援用として折り畳み式の橋は実在します。(〇)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND rc.title = 'ほんとうにあるのは？' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '実在する', TRUE, 1 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND rc.title = 'ほんとうにあるのは？' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '実在しない（架空のもの）', FALSE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 47 AND rc.title = 'ほんとうにあるのは？' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
