-- Reading Content: 竹取物語
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '竹取物語', '昔、ある所におじいさんとおばあさんが住んでいました。おじいさんは山から竹を取ってきて、いろいろな物を作って売っていました。

ある日、おじいさんは根元が光り輝く不思議な竹を見つけました。切ってみると、中に三寸（約9センチ）ほどの小さな可愛い女の子がいました。子どものいない二人は大喜びで、その子に「かぐや姫」と名付けて大切に育てました。かぐや姫はわずか3か月で美しい娘に成長しました。

かぐや姫の美しさは国中に知れ渡り、5人の貴公子が結婚を申し込みました。しかし、かぐや姫は「インドにある仏の石の鉢」「蓬莱の玉の枝」「火鼠の皮衣」「竜の首の珠」「燕の子安貝」という手に入らない宝物を持ってくるように頼みました。5人は誰も本物を持ってくることができませんでした。

やがて帝（天皇）もかぐや姫に心を寄せましたが、かぐや姫は求婚を断りました。そして8月十五夜の満月の夜、月の使者が雲に乗って迎えに来ました。かぐや姫は帝に不死の薬と手紙を残し、羽衣を着て月の世界へ帰っていきました。', 'Ngày xửa ngày xưa, ở một ngôi làng nọ có hai ông bà lão nghèo sống nương tựa vào nhau. Hàng ngày ông lão lên núi đốn tre đem về đan lát bán kiếm sống.

Một ngày nọ, ông lão bắt gặp một thân tre phát ra ánh sáng lung linh kỳ ảo. Khi chặt tre ra, ông kinh ngạc thấy một bé gái tí hon xinh xắn chỉ cao khoảng 9 cm nằm bên trong. Hai ông bà lão hiếm muộn vô cùng sung sướng nhận nuôi bé, đặt tên là ''Kaguya-hime'' (Nàng tiên tre). Chỉ sau 3 tháng, bé gái đã lớn bổng thành một thiếu nữ tuyệt sắc giai nhân.

Sắc đẹp của nàng vang danh khắp cả nước. 5 vị công tử quý tộc danh giá đến cầu hôn. Nàng đưa ra thử thách yêu cầu họ tìm những bảo vật hiếm có không thể tìm thấy trên trần gian như ''Bát đá của Đức Phật ở Ấn Độ'', ''Cành cây ngọc trên núi Bồng Lai'', ''Áo lông chuột lửa'', ''Ngọc trên cổ rồng'', ''Vỏ sò sinh nở của chim nhạn''. Kết quả không ai đem về được bảo vật thật.

Ngay cả Nhật hoàng sau đó đem lòng si mê cầu hôn nhưng nàng cũng từ chối. Vào đêm rằm tháng 8 trăng sáng vằng vặc, những sứ giả cung trăng cưỡi mây hạ phàm đón nàng. Nàng để lại cho Nhật hoàng viên thuốc trường sinh bất tử và phong thư từ biệt, rồi khoác áo lông vũ bay về cung trăng.', '/media/reading/reading_n4_l48_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '竹取物語');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) おじいさんは光る竹の中からかぐや姫を見つけた。', 'MULTIPLE_CHOICE', '光る竹を切ったところ、中に小さな女の子（かぐや姫）がいました。(〇)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND rc.title = '竹取物語' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
