INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '3) かぐや姫は満月の晩にどこへ帰っていきましたか。', 'MULTIPLE_CHOICE', 'かぐや姫は月の世界から来た者であり、月の世界へ帰っていきました。', NULL, 3 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 48 AND rc.title = '竹取物語' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 3);
