-- Reading Content: 人生
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, '人生', '【披露宴でのスピーチ（1993年）】
「新郎の宝田太郎君と新婦の花子さんのご結婚を祝福いたします。太郎君は京都大学を卒業後、アップル銀行に入行され、アメリカ留学も経験された優秀な青年です。花子さんはニューヨーク生まれで、パリやロンドンでデザインを学ばれました。お二人の輝かしい門出をお祝い申し上げます。」

【金婚式でのスピーチ（2043年）】
「結婚50周年、おめでとうございます！ 50年という長い歳月、山あり谷あり、様々なことがあったことでしょう。喧嘩をすることもあったでしょうが、いつも手を携えて仲睦まじく歩んでこられました。これからもお二人でお元気で、ダイヤモンド婚式を目指してください。」

【お別れ会でのスピーチ（2060年）】
「宝田太郎さん、90歳で天寿を全うされました。愛する花子さんと共に歩まれた人生は、本当に豊かで実り多きものでした。去年先に旅立たれた奥様と、今頃天国で再会されていることでしょう。どうぞ安らかにお眠りください。」', '[Lời chúc mừng tại tiệc cưới (Năm 1993)]
''Chúc mừng đám cưới chú rể Tairada Taro và cô dâu Hanako. Anh Taro tốt nghiệp Đại học Kyoto, công tác tại Ngân hàng Apple và từng du học tại Mỹ. Chị Hanako sinh ra tại New York, từng theo học thiết kế tại Paris và London. Xin chúc cho chặng đường mới của hai bạn tràn ngập hạnh phúc.''

[Lời chúc mừng đám cưới vàng (Năm 2043)]
''Chúc mừng kỷ niệm 50 năm ngày cưới của anh chị! Tròn nửa thế kỷ cùng đi bên nhau, chắc hẳn đã trải qua bao thăng trầm và kỷ niệm sâu sắc. Dù đôi khi có bất đồng, anh chị vẫn luôn nắm chặt tay nhau vượt qua. Chúc hai bác sống vui khỏe hướng tới kỷ niệm đám cưới kim cương.''

[Lời tưởng niệm tại tang lễ (Năm 2060)]
''Ông Tairada Taro đã hưởng thọ 90 tuổi viên mãn. Cuộc đời gắn bó cùng người vợ dấu yêu Hanako thực sự tràn ngập niềm vui và ý nghĩa. Giờ này chắc ông đã được gặp lại người bạn đời đã khuất bóng vào năm ngoái ở chốn thiên đường. Cầu mong linh hồn ông yên nghỉ thanh thản.''', '/media/reading/reading_n4_l49_r01.png', 1 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = '人生');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 太郎と花子は結婚して50周年（金婚式）を迎えることができた。', 'MULTIPLE_CHOICE', '結婚50周年のスピーチが行われています。(〇)', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND rc.title = '人生' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '〇', TRUE, 1 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND rc.title = '人生' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 1);
INSERT INTO reading_options (question_id, content, is_correct, sort_order) SELECT rq.id, '✕', FALSE, 2 FROM reading_questions rq JOIN reading_contents rc ON rq.reading_id = rc.id JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND rc.title = '人生' AND rq.sort_order = 1 AND NOT EXISTS (SELECT 1 FROM reading_options ro WHERE ro.question_id = rq.id AND ro.sort_order = 2);
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '2) 太郎さんは90歳で亡くなったとき、妻の花子さんはまだ生きていた。', 'MULTIPLE_CHOICE', '「去年先に旅立たれた奥様」とあり、花子さんのほうが先に亡くなっています。(✕)', NULL, 2 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND rc.title = '人生' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 2);
