-- Reading Content: あいさつ状
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'あいさつ状', '日本の手紙やはがきでよく使われる季節のあいさつ状：

1. 《年賀状（お正月）》
「明けましておめでとうございます。今年もよろしくお願いいたします。」

2. 《結婚祝い・招待状の返信》
「ご結婚おめでとうございます。喜んで出席させていただきます。」

3. 《暑中見舞い（夏）》
「暑中お見舞い申し上げます。暑さ厳しき折、皆様いかがお過ごしでしょうか。どうぞお体に気をつけてお過ごしください。」

4. 《秋のあいさつ》
「紅葉が美しい季節になりました。皆様いかがお過ごしでしょうか。」', 'Các mẫu thiệp chào hỏi theo mùa phổ biến ở Nhật Bản:

1. Thiệp chúc mừng năm mới (Nengajo): ''Chúc mừng năm mới. Năm nay cũng xin được giúp đỡ.''
2. Hồi âm thiệp mời cưới: ''Chúc mừng hạnh phúc hai bạn. Tôi rất vui lòng và vinh dự được tham dự.''
3. Thăm hỏi mùa hè oi bức (Shochu-mimai): ''Kính chúc quý bạn an lành giữa mùa hè oi ả. Xin hãy giữ gìn sức khỏe.''
4. Lời chúc mùa thu lá đỏ: ''Mùa lá đỏ Momiji đã về tuyệt đẹp. Chúc quý bạn vạn sự như ý.''', '/media/reading/reading_n4_l49_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'あいさつ状');
INSERT INTO reading_questions (reading_id, question, question_type, explanation, image_url, sort_order) SELECT rc.id, '1) 夏の暑い時期に相手の健康を気遣って送るあいさつ状はどれですか。', 'MULTIPLE_CHOICE', '夏のあいさつ状は「暑中見舞い（しょちゅうみまい）」です。', NULL, 1 FROM reading_contents rc JOIN lessons ls ON rc.lesson_id = ls.id JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 49 AND rc.title = 'あいさつ状' AND NOT EXISTS (SELECT 1 FROM reading_questions rq WHERE rq.reading_id = rc.id AND rq.sort_order = 1);
