-- Reading Content: お会いできて、うれしいです
INSERT INTO reading_contents (lesson_id, title, content, translation, image_url, sort_order) SELECT ls.id, 'お会いできて、うれしいです', '20世紀から現代にかけて人類に大きな影響を与えた偉人たち：

1. 《アルフレッド・ノーベル（スウェーデン）》
ダイナマイトを発明したが、戦争で多くの人が命を落としたことに心を痛め、遺産を平和や科学の発展に尽くした人々に贈る「ノーベル賞」を創設した。

2. 《パブロ・ピカソ（スペイン）》
20世紀を代表する画家。スペイン内戦の悲劇と平和への祈りを込めて大作『ゲルニカ』を描いた。

3. 《オードリー・ヘプバーン（ベルギー／イギリス）》
『ローマの休日』などで世界中を魅了した女優。晩年はユニセフ親善大使として世界中の恵まれない子どもたちの支援に生涯を捧げた。

4. 《マザー・テレサ（北マケドニア／インド）》
インドのコルカタで貧しい人や病気の人々の救済に生涯を捧げ、ノーベル平和賞を受賞した修道女。', 'Những vĩ nhân thế kỷ 20 để lại dấu ấn sâu sắc cho nhân loại:

1. Alfred Nobel (Thụy Điển): Người phát minh ra thuốc nổ Dynamite, nhưng xót xa trước việc nó bị dùng trong chiến tranh, ông đã để lại toàn bộ tài sản thành lập giải thưởng Nobel vinh danh các cống hiến cho hòa bình và khoa học.
2. Pablo Picasso (Tây Ban Nha): Danh họa thế kỷ 20, đã vẽ kiệt tác ''Guernica'' phản đối chiến tranh và nguyện cầu cho hòa bình thế giới.
3. Audrey Hepburn: Huyền thoại điện ảnh với tác phẩm ''Kỳ nghỉ ở La Mã'', những năm tháng cuối đời đã cống hiến hết mình cho sứ mệnh Đại sứ Thiện chí UNICEF giúp đỡ trẻ em nghèo toàn cầu.
4. Mẹ Teresa: Nữ tu sĩ cống hiến trọn cuộc đời cứu giúp những người nghèo khổ, bệnh tật cùng cực tại Kolkata (Ấn Độ), được trao giải Nobel Hòa bình.', '/media/reading/reading_n4_l50_r02.png', 2 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND NOT EXISTS (SELECT 1 FROM reading_contents WHERE lesson_id = ls.id AND title = 'お会いできて、うれしいです');
